.5; //Convert voltage value to TDS value\n\n    if (data.size() == max_size) {\n        data.pop();//this is used to remove the first read variable\n    }\n    data.push(tdsValue); //read variables and store in data\n\n    //Settings for the line graph title\n    auto header =  text(0, 0)\n                .value("TDS Reading")\n                .align(center)\n                .valign(vcenter)\n                .width(tft.width())\n                .thickness(3);\n\n    header.height(header.font_height() * 2);\n    header.draw(); //Header height is the twice the height of the font\n\n  //Settings for the line graph\n    auto content = line_chart(20, header.height()); //(x,y) where the line graph begins\n         content\n                .height(tft.height() - header.height() * 1.5) //actual height of the line chart\n                .width(tft.width() - content.x() * 2) //actual width of the line chart\n                .based_on(0.0) //Starting point of y-axis, must be a float\n                .show_circle(true) //drawing a cirle at each point, default is on.\n                .value(data) //passing through the data to line graph\n                .color(TFT_RED) //Setting the color for the line\n                .draw();\n\n    spr.pushSprite(0, 0);\n    delay(50);\n}\n'})}),"\n",(0,t.jsx)(e.h2,{id:"wio-terminal-\u4E0E-grove---oled-\u663E\u793A\u5C4F",children:"Wio Terminal \u4E0E Grove - OLED \u663E\u793A\u5C4F"}),"\n",(0,t.jsxs)(e.p,{children:["\u5982\u679C\u60A8\u9700\u8981\u4E00\u4E2A\u7B2C\u4E8C\u5C4F\u5E55\u4E0E Wio Terminal \u4E00\u8D77\u663E\u793A\uFF0C",(0,t.jsx)(e.strong,{children:'Grove - OLED \u663E\u793A\u5C4F 0.96"'})," \u5C06\u662F\u5B8C\u7F8E\u7684\u9009\u62E9\u3002\u5B83\u53EF\u4EE5\u7528\u6765\u663E\u793A\u56FE\u5F62\u548C\u6570\u636E\uFF0C\u4E3A Wio Terminal \u589E\u52A0\u66F4\u591A\u4EA4\u4E92\u529F\u80FD\u3002"]}),"\n",(0,t.jsx)(e.h3,{id:"\u5E93\u5B89\u88C5-1",children:"\u5E93\u5B89\u88C5"}),"\n",(0,t.jsxs)(e.ol,{children:["\n",(0,t.jsxs)(e.li,{childre